'use strict';

// MODULES //

var tape = require( 'tape' );
var instanceOf = require( '@stdlib/assert/instance-of' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var Padding = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Padding, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function is a constructor', function test( t ) {
	var padding = new Padding();
	t.strictEqual( instanceOf( padding, Padding ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor does not require the `new` keyword', function test( t ) {
	var padding;
	var ctor;

	ctor = Padding;
	padding = ctor();
	t.strictEqual( instanceOf( padding, Padding ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor does not require the `new` keyword (options)', function test( t ) {
	var padding;
	var ctor;

	ctor = Padding;
	padding = ctor({
		'top': 10
	});
	t.strictEqual( instanceOf( padding, Padding ), true, 'returns expected value' );
	t.strictEqual( padding.top, 10, 'returns expected value' );
	t.end();
});

tape( 'the constructor throws an error if provided an options argument which is not an object', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		null,
		void 0,
		true,
		false,
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var padding = new Padding( value ); // eslint-disable-line no-unused-vars
		};
	}
});

tape( 'the constructor has a read-only `name` property', function test( t ) {
	t.strictEqual( Padding.name, 'Padding', 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance having a `toJSON` method for serializing an instance to JSON', function test( t ) {
	var expected;
	var padding;
	var json;

	padding = new Padding();
	json = padding.toJSON();

	expected = {
		'bottom': 0,
		'left': 0,
		'right': 0,
		'top': 0
	};
	t.deepEqual( json, expected, 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance having a `toJSON` method for serializing an instance to JSON (options)', function test( t ) {
	var expected;
	var padding;
	var json;

	padding = new Padding({
		'bottom': 10,
		'left': 20,
		'right': 30,
		'top': 40
	});
	json = padding.toJSON();

	expected = {
		'bottom': 10,
		'left': 20,
		'right': 30,
		'top': 40
	};
	t.deepEqual( json, expected, 'returns expected value' );
	t.end();
});

tape( 'the `toJSON` method is implicitly invoked by `JSON.stringify`', function test( t ) {
	var expected;
	var padding;

	padding = new Padding({
		'top': 10
	});

	expected = {
		'bottom': 0,
		'left': 0,
		'right': 0,
		'top': 10
	};
	t.strictEqual( JSON.stringify( padding ), JSON.stringify( expected ), 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance which inherits from EventEmitter', function test( t ) {
	var padding;

	padding = new Padding();

	t.strictEqual( typeof padding.on, 'function', 'returns expected value' );
	t.strictEqual( typeof padding.emit, 'function', 'returns expected value' );
	t.strictEqual( typeof padding.removeListener, 'function', 'returns expected value' );

	t.end();
});

tape( 'the constructor ignores unrecognized options', function test( t ) {
	var padding;

	padding = new Padding({
		'top': 10,
		'beep': 'boop',
		'foo': 'bar'
	});

	t.strictEqual( padding.top, 10, 'returns expected value' );
	t.strictEqual( hasOwnProp( padding, 'beep' ), false, 'returns expected value' );
	t.strictEqual( hasOwnProp( padding, 'foo' ), false, 'returns expected value' );

	t.end();
});
